// ============================================================
// AIDL Juniors — ROUTE-MAP MODULE LESSONS · generator + CADET pack
// One playable lesson per route-map module. IDs: JM-01… / TM-01…
// (first number of a ranged module, e.g. M25–26 -> JM-25).
// Registered on window.AIDL_JR_LESSONS. Chained via `next` in
// route-map order, so Finish -> next module, semester after semester.
// ============================================================

window.AIDL_JR_REGISTER_MODULES = function (opts) {
  const P = window.AIDL_JR_LESSONS;
  const pad = n => String(n).padStart(2, '0');
  const flat = [];
  opts.sems.forEach((sem, si) => sem.mods.forEach(m => flat.push(Object.assign({}, m, { sem: si + 1, semName: sem.name }))));
  flat.forEach(m => {
    m.first = parseInt(String(m.n).match(/\d+/)[0], 10);
    m.id = opts.prefix + pad(m.first);
  });
  const exItems = arr => (arr || []).map(s => {
    const i = s.indexOf('|');
    return { kind: s.slice(0, i) === 'g' ? 'good' : 'bad', text: s.slice(i + 1) };
  });
  flat.forEach((m, i) => {
    const nx = flat[i + 1] || null;
    const NAME = m.name.toUpperCase();
    const segs = [];
    let t = 0;
    const push = (kind, dur, title, eyeKind, body) => {
      segs.push({ idx: segs.length + 1, kind, start: t, end: (t += dur), title, eyebrow: 'STOP ' + pad(segs.length + 1) + ' · ' + eyeKind, body });
    };
    // 1 · Briefing — straight from the route map row
    push('concept', 240, 'BRIEFING · ' + NAME, 'BRIEFING', {
      template: 'jrconcept',
      sign: { kind: 'circle', glyph: 'M' + m.first },
      sub: 'MODULE ' + m.n + ' OF ' + opts.total + ' · SEMESTER ' + m.sem + ' · ' + m.semName.toUpperCase(),
      heading: m.name,
      paragraphs: [
        '<strong>Today\u2019s drive:</strong> ' + m.act,
        opts.level === 'J'
          ? 'This stop is <strong>Module ' + m.n + '</strong> on your route map \u2014 semester ' + m.sem + ', \u201c' + m.semName + '\u201d.'
          : 'Route position: <strong>Module ' + m.n + '</strong> \u00b7 semester ' + m.sem + ' \u00b7 \u201c' + m.semName + '\u201d.',
      ],
      examples: { title: 'Today\u2019s route', items: [
        { kind: 'good', text: 'Learn the big idea behind \u201c' + m.name + '\u201d' },
        { kind: 'good', text: m.actShort || 'Do the hands-on activity' },
        { kind: 'good', text: 'Pass the quick check to earn your stars' },
      ] },
      callout: { title: '\u27e8 \u27e9 Swap point', body: m.hook + ' \u2014 your teacher repaints this bit for YOUR town.' },
    });
    // 2 · Learn — hand-written core concept
    push('concept', 480, 'LEARN · ' + (m.lt || NAME), 'LEARN', {
      template: 'jrconcept',
      sign: { kind: m.sign || 'rect', glyph: m.glyph || 'AI' },
      sub: m.lsub || '',
      heading: m.h,
      paragraphs: m.p,
      examples: m.ex ? { title: m.ex.t, items: exItems(m.ex.i) } : undefined,
      callout: m.co ? { title: m.co[0], body: m.co[1], icRed: !!m.co[2], icIcon: m.co[2] ? '!' : undefined } : undefined,
    });
    // 3 · Activity — sort game or builder
    if (m.sort) {
      push('jrsort', 600, 'GAME · ' + (m.sort.name || 'SORT IT'), 'SORTING GAME', {
        template: 'jrsort', prompt: m.sort.prompt,
        greenLabel: m.sort.g, redLabel: m.sort.r, intro: m.sort.intro,
        items: m.sort.items.map(s => { const j = s.lastIndexOf('|'); return { text: s.slice(0, j), answer: s.slice(j + 1) }; }),
      });
    } else {
      push('jrbuilder', 600, 'YOUR TURN · ' + (m.bt || 'BUILD IT'), 'MAKER LANE', {
        template: 'jrbuilder', scenario: m.build,
      });
    }
    // 4 · Quick check
    push('quiz', 360, 'QUICK CHECK · ' + (m.qt || NAME), 'QUICK CHECK', {
      template: 'jrquiz',
      question: m.quiz.q,
      options: m.quiz.o.map(s => { const parts = s.split('|'); return { letter: parts[0], text: parts[1], right: parts[2] === '1' }; }),
      rightFeedback: ' ' + m.quiz.rf,
      wrongFeedback: ' ' + m.quiz.wf,
    });
    // 5 · Wrap
    push('reflect', 300, 'WRAP · ' + NAME, 'WRAP-UP', {
      template: 'jrreflect',
      learned: m.learned,
      take: m.take,
      next: nx
        ? '<b>M' + nx.n + ' \u00b7 ' + nx.name + '.</b> ' + (nx.sem !== m.sem ? 'New semester: \u201c' + nx.semName + '\u201d!' : 'Next stop on your route map.')
        : '<b>Route complete!</b> That was the last module \u2014 licence ceremony time. \ud83c\udf93',
    });
    P[m.id] = {
      id: m.id, level: opts.level, next: nx ? nx.id : null,
      title: m.id + ' \u00b7 M' + m.n + ' \u00b7 ' + m.name,
      titleTop: 'M' + m.n + ' \u00b7 ' + NAME,
      sub: opts.tierName.toUpperCase() + ' \u00b7 AGES ' + opts.ages + ' \u00b7 SEMESTER ' + m.sem + ' \u00b7 MODULE ' + m.n + ' OF ' + opts.total + ' \u00b7 33 MIN \u00b7 EARN 2 STARS',
      duration: t,
      instructor: opts.instructor, instructorRole: opts.instructorRole,
      starGoal: 2,
      segments: segs,
      commentary: [
        { t: 0, kind: 'msg', text: opts.hi + ' Module ' + m.n + ': <b>' + m.name + '</b>. ' + (opts.level === 'J' ? 'Buckle up! \ud83d\ude97' : 'Let\u2019s work.') },
        { t: 260, kind: 'note', text: 'Swap point on this stop: ' + m.hook + '.' },
        { t: 760, kind: 'note', text: opts.level === 'J' ? 'Activity time! Take it slow \u2014 stars wait for you.' : 'Hands-on segment \u2014 document what you do; process is gold.' },
        { t: 1340, kind: 'warn', text: 'Quick check ahead. ' + (opts.level === 'J' ? 'You\u2019ve got this!' : 'One question, no tricks \u2014 just the core idea.') },
        { t: 1700, kind: 'msg', text: nx ? 'Nice driving! Next on the route map: M' + nx.n + ' \u00b7 ' + nx.name + '.' : 'That\u2019s the FINAL module. So proud of you!' },
      ],
    };
  });
};

// ------------------------------------------------------------
// CADET · Junior Cadet 8–12 · 32 modules · instructor BUDDY
// ------------------------------------------------------------
window.AIDL_JR_REGISTER_MODULES({
  level: 'J', prefix: 'JM-', total: 32, tierName: 'Junior Cadet', ages: '8\u201312',
  instructor: 'BUDDY', instructorRole: 'YOUR AI BUDDY \u00b7 CLASS J \u00b7 CADET',
  hi: 'Hi, it\u2019s Buddy! \ud83e\udd16',
  sems: [
    { name: 'AI Around My Home & Street', mods: [
      { n: 1, name: 'Machine or Human?', act: 'Sorting game: cards showing local services \u2014 bus announcement, market vendor, weather alert, radio DJ. Which involve AI?', hook: 'Cards redrawn with \u27e8local transport, shops & media\u27e9', actShort: 'Sort real services: machine or human?',
        sign: 'octagon', glyph: 'AI?', h: 'Some voices are people. Some are programs.',
        p: ['Every day you hear announcements, alerts, and helpers. Some come from a <strong>person</strong>, some from a <strong>machine</strong> \u2014 and some machines use <strong>AI</strong>: programs that learned from lots of examples.', 'A recorded voice is NOT AI \u2014 it just plays back. AI <strong>decides</strong> something: what to say, what you meant, what comes next.'],
        ex: { t: 'Spot the difference', i: ['g|Weather app choosing tomorrow\u2019s forecast \u2192 AI', 'g|Voice assistant understanding your question \u2192 AI', 'b|A doorbell that just rings \u2192 machine, not AI', 'b|The market vendor \u2192 a human!'] },
        co: ['Detective tip', 'Ask: did something LEARN or DECIDE here? If yes \u2014 AI is probably on board.'],
        sort: { name: 'MACHINE OR HUMAN?', prompt: 'Sort these things you meet around town:', g: 'USES AI \ud83e\udd16', r: 'HUMAN / NO AI \ud83d\udc64', intro: 'GREEN = a program decides something. RED = a person, or a plain machine.', items: ['Bus app predicting \u201carrives in 4 min\u201d|green', 'The radio DJ picking songs live|red', 'Phone unlocking when it sees your face|green', 'A kettle switching off when it boils|red', 'Weather alert predicting a storm|green', 'The market vendor giving change|red', 'Video app suggesting what to watch next|green', 'A recorded \u201cmind the doors\u201d announcement|red'] },
        quiz: { q: 'Which of these is most likely using AI?', o: ['A|A light switch turning on a lamp', 'B|A phone keyboard guessing your next word|1', 'C|A paper timetable at the bus stop'], rf: 'The keyboard <b>learned</b> from millions of sentences to guess what comes next \u2014 that\u2019s AI.', wf: 'A switch and a paper timetable never learn or decide. The keyboard <b>guesses</b> from patterns \u2014 that\u2019s the AI.' },
        learned: 'How to spot AI around your town: if a machine <b>learned</b> or <b>decides</b>, AI is on board \u2014 recordings and plain machines don\u2019t count.', take: 'Play detective this week: find one AI and one not-AI machine at home, and tell someone WHY you sorted them that way.' },
      { n: 2, name: 'The Robot Teacher Game', act: 'One child is the \u201crobot\u201d; others write step-by-step rules to make it walk across the room or make a local dish.', hook: 'Instruction set is a \u27e8local recipe or dance\u27e9', actShort: 'Program a human robot with exact steps',
        sign: 'rect', glyph: 'STEP 1', h: 'Computers do EXACTLY what you say', lt: 'EXACT STEPS',
        p: ['A computer follows instructions <strong>exactly</strong> \u2014 no guessing, no \u201cyou know what I mean\u201d. If your rule says \u201cwalk forward\u201d, the robot walks into the wall!', 'That\u2019s called an <strong>algorithm</strong>: a list of steps so clear that even a machine (or a blindfolded friend) can follow it.'],
        ex: { t: 'Fuzzy rule vs. robot rule', i: ['b|\u201cGo over there\u201d \u2014 where?!', 'g|\u201cTake 3 steps forward, then stop\u201d', 'b|\u201cAdd some flour\u201d \u2014 how much?', 'g|\u201cAdd 2 cups of flour, then stir 10 times\u201d'] },
        co: ['Why it matters', 'AI seems clever, but underneath it\u2019s still following steps. Clear steps in \u2192 good results out.'],
        build: 'Be the programmer! Write robot-proof instructions for making your favourite local snack (or dance move). CLEAR: every step exact. KIND: imagine your robot friend following it. SAFE: nothing private \u2014 just the steps.',
        quiz: { q: 'Your \u201crobot\u201d friend gets the rule \u201cput the bread in\u201d and stands still. Why?', o: ['A|The robot is being silly', 'B|The rule doesn\u2019t say in WHAT, or how \u2014 it\u2019s not exact enough|1', 'C|Robots can\u2019t follow rules'], rf: 'Exactly \u2014 machines need every step spelled out. \u201cIn the toaster, sideways, then press the lever\u201d works!', wf: 'The robot isn\u2019t silly \u2014 the <b>rule</b> is fuzzy. Machines need every step spelled out.' },
        learned: 'What an <b>algorithm</b> is \u2014 steps so exact a machine can follow them \u2014 and why fuzzy instructions break robots.', take: 'When AI gives a weird answer, check your instructions first: were they robot-proof?' },
      { n: 3, name: 'How Machines See', act: 'Pixel-grid coloring: turn a photo of a local landmark into a grid and discover that images are numbers.', hook: 'Landmark = \u27e8your town\u2019s mosque / temple / church / bridge / mountain\u27e9', actShort: 'Turn a picture into a number grid',
        sign: 'circle', glyph: '\ud83d\udc41', h: 'Pictures are secretly numbers', lt: 'PIXELS',
        p: ['Zoom way, way in on any photo and you find tiny squares called <strong>pixels</strong>. Each pixel is just a <strong>number</strong> saying how bright or what colour it is.', 'So when a machine \u201csees\u201d your town\u2019s landmark, it\u2019s really reading a giant grid of numbers and finding <strong>patterns</strong> in them \u2014 edges, shapes, corners.'],
        ex: { t: 'What the machine really gets', i: ['g|A 100\u00d7100 photo = 10,000 numbers', 'g|Bright pixel = big number, dark pixel = small', 'b|The machine does NOT \u201cknow\u201d it\u2019s your temple \u2014 it matches patterns'] },
        co: ['Mind = blown', 'Every photo you\u2019ve ever taken is numbers. Machines never see like eyes do \u2014 they calculate.'],
        sort: { name: 'SEEING LIKE A MACHINE', prompt: 'Which of these would a machine find EASY to see, and which HARD?', g: 'EASY FOR MACHINES \ud83d\udfe2', r: 'HARD FOR MACHINES \ud83d\udd34', intro: 'GREEN = clear pattern in the pixels. RED = confusing pixels (dark, blurry, hidden).', items: ['A landmark on a bright sunny day|green', 'The same landmark in thick fog|red', 'A big clear STOP sign|green', 'A sign half-covered by a tree|red', 'Your face looking straight at the camera|green', 'Your face in a dark room|red'] },
        quiz: { q: 'What does a machine actually receive when it \u201clooks at\u201d a photo?', o: ['A|A grid of numbers, one per pixel|1', 'B|A tiny copy of the real place', 'C|The same feeling we get looking at it'], rf: 'Pictures ARE numbers to a machine \u2014 it finds patterns in the grid.', wf: 'Machines don\u2019t see places or feel anything \u2014 they get a grid of <b>numbers</b> and hunt for patterns.' },
        learned: 'Images are <b>pixel numbers</b>, and machine \u201cseeing\u201d is pattern-finding in those numbers \u2014 which is why fog and darkness confuse it.', take: 'Next time an app recognises something, remember: it matched number patterns \u2014 it didn\u2019t \u201csee\u201d like you do.' },
      { n: 4, name: 'How Machines Hear', act: 'Clap-pattern game; visualize sound waves with rice on a drum; local-language voice assistant demo on the teacher\u2019s device.', hook: 'Test whether assistants understand \u27e8the local accent / dialect\u27e9 \u2014 discuss why not', actShort: 'See sound as waves \u2014 and test the local accent',
        sign: 'circle', glyph: '\ud83d\udc42', h: 'Sound is a wiggly line of numbers', lt: 'SOUND WAVES',
        p: ['Sound is air wiggling. A microphone turns those wiggles into \u2014 you guessed it \u2014 <strong>numbers</strong>. Machines match the wiggle-patterns to words they\u2019ve heard before.', 'Here\u2019s the catch: if a machine mostly learned from ONE way of speaking, it struggles with <strong>other accents and languages</strong>. That\u2019s not your fault \u2014 it\u2019s a gap in what the machine was taught.'],
        ex: { t: 'Why assistants mishear', i: ['g|Heard millions of examples of one accent \u2192 great at it', 'b|Few examples of YOUR accent \u2192 mistakes', 'b|Background noise scrambles the wiggle-pattern'] },
        co: ['Say it proudly', 'If an assistant can\u2019t understand your accent, the MACHINE needs better examples \u2014 your voice is not wrong.', true],
        quiz: { q: 'A voice assistant keeps misunderstanding Grandma\u2019s accent. What\u2019s the most likely reason?', o: ['A|Grandma is speaking incorrectly', 'B|It wasn\u2019t trained on enough voices like hers|1', 'C|The assistant is broken'], rf: 'Machines only understand what they had examples of. More voices like Grandma\u2019s in training = better hearing.', wf: 'Grandma\u2019s fine and it isn\u2019t broken \u2014 it just never got enough <b>examples</b> of accents like hers.' },
        sort: { name: 'WILL IT HEAR ME?', prompt: 'Sort: when will the assistant likely understand?', g: 'LIKELY UNDERSTANDS \ud83d\udfe2', r: 'LIKELY STRUGGLES \ud83d\udd34', intro: 'GREEN = clear, common speech patterns. RED = things it had few examples of.', items: ['Slow, clear question in a common accent|green', 'A word from the local dialect|red', 'Talking while the TV blasts|red', 'One short question in a quiet room|green', 'A song lyric in the local language|red', 'Counting \u201cone two three\u201d|green'] },
        learned: 'Machines hear by matching <b>wiggle-patterns</b> (numbers again!) \u2014 and they\u2019re only good at voices they had lots of examples of.', take: 'If it mishears you, it\u2019s a data gap, not you. Try clearer + quieter, and tell a grown-up what it got wrong.' },
      { n: 5, name: 'Pattern Detectives', act: 'Sort seeds, buttons, or fabric scraps by features; compare human sorting vs. \u201cmachine rules\u201d.', hook: 'Sort \u27e8local crops, spices, or textile patterns\u27e9', actShort: 'Sort real things by features, like a machine',
        sign: 'triangle', glyph: '?', h: 'Features: how machines tell things apart', lt: 'FEATURES',
        p: ['When you sort seeds or buttons you notice <strong>features</strong>: big/small, rough/smooth, light/dark. Machines do the same \u2014 but only with features someone measured.', 'Pick GOOD features and sorting is easy. Pick BAD ones (like \u201cthings I like\u201d) and everything ends up in a muddle. Machines have the exact same problem!'],
        ex: { t: 'Good vs. bad features', i: ['g|Colour, size, shape \u2014 easy to measure', 'g|\u201cHas stripes\u201d \u2014 yes or no, clear!', 'b|\u201cLooks nice\u201d \u2014 everyone disagrees', 'b|\u201cFeels lucky\u201d \u2014 can\u2019t measure it'] },
        co: ['Detective badge', 'Sorting by clear features is EXACTLY what AI classifiers do. You just did machine learning \u2014 with your hands.'],
        sort: { name: 'FEATURE OR FEELING?', prompt: 'Which of these could a machine actually use to sort things?', g: 'MEASURABLE FEATURE \ud83d\udfe2', r: 'JUST A FEELING \ud83d\udd34', intro: 'GREEN = you could measure or count it. RED = fuzzy, changes person to person.', items: ['Length in centimetres|green', 'How pretty it is|red', 'Number of stripes|green', 'Whether it seems friendly|red', 'Colour: red, yellow or green|green', 'How lucky it feels|red'] },
        quiz: { q: 'A machine must sort mangoes from lemons. Which feature works best?', o: ['A|Which fruit tastes better', 'B|Size and colour|1', 'C|Which one the farmer likes'], rf: 'Size and colour can be measured from a photo \u2014 perfect features for a machine.', wf: 'Taste and liking can\u2019t be measured from a photo. <b>Size and colour</b> can \u2014 that\u2019s what machines use.' },
        learned: 'Machines sort the world using <b>features</b> \u2014 measurable clues like size, colour and shape. Good features = good sorting.', take: 'You\u2019re a pattern detective now: when AI sorts something, ask \u201cwhat features is it using?\u201d' },
      { n: 6, name: 'Smart or Just Fast?', act: 'Calculator vs. thinking debate; story circle about cleverness and wisdom.', hook: 'A \u27e8local folktale\u27e9 about cleverness vs. wisdom', actShort: 'Debate: is a calculator smart?',
        sign: 'octagon', glyph: 'FAST \u2260 WISE', h: 'Fast is not the same as wise', lt: 'SMART VS. FAST',
        p: ['A calculator beats every human at 4,725 \u00d7 39. Is it smart? It\u2019s <strong>fast</strong> \u2014 but it doesn\u2019t know WHY you\u2019re multiplying, or whether you should.', 'AI is like that too: brilliant speed, mountains of facts \u2014 but no <strong>wisdom</strong>. Wisdom means knowing what matters, what\u2019s kind, and when to stop. That part is yours.'],
        ex: { t: 'Fast brain vs. wise heart', i: ['g|AI: reads a million pages in a blink', 'g|You: know your little sister needs cheering up', 'b|AI: doesn\u2019t know your family, your town, or what\u2019s right', 'g|You: decide what SHOULD be done'] },
        co: ['From the story circle', 'In every folktale, the truly wise one isn\u2019t the fastest \u2014 it\u2019s the one who knows what matters. Machines are the fast one.'],
        quiz: { q: 'What can YOU do that the fastest AI cannot?', o: ['A|Multiply big numbers quickly', 'B|Remember lots of facts', 'C|Decide what is kind and right for the people you love|1'], rf: 'Speed and memory are machine tricks. Caring, judging and choosing wisely \u2014 that\u2019s human.', wf: 'Machines beat us at speed and memory. What they can\u2019t do is <b>care</b> or judge what\u2019s right \u2014 that\u2019s you.' },
        sort: { name: 'SMART OR JUST FAST?', prompt: 'Sort these abilities:', g: 'WISDOM \u2014 HUMAN \ud83d\udfe2', r: 'SPEED \u2014 MACHINE \ud83d\udd34', intro: 'GREEN = needs caring and judgement. RED = needs speed or memory.', items: ['Adding 1,000 numbers in a second|red', 'Knowing your friend is sad before they say so|green', 'Remembering every book in the library|red', 'Choosing to share your snack|green', 'Finding a word in a million pages|red', 'Deciding a joke would hurt someone|green'] },
        learned: 'The difference between <b>fast</b> (machines: speed + memory) and <b>wise</b> (humans: care + judgement).', take: 'Let AI be your fast helper \u2014 but keep the wise decisions, the kind ones, for yourself.' },
      { n: 7, name: 'My Data Shadow', act: 'Trace your day: what info did machines collect? Draw your \u201cdata shadow\u201d.', hook: '\u27e8Local transit cards, shop cameras, phone apps\u27e9', actShort: 'Map what machines learned about you today',
        sign: 'octagon', glyph: 'DATA', h: 'You leave footprints machines can read', lt: 'DATA SHADOW',
        p: ['Tap a transit card, pass a shop camera, play a game app \u2014 each one collects a little <strong>data</strong> about you. Added up, it makes your <strong>data shadow</strong>: a picture of your day you never meant to draw.', 'Data isn\u2019t evil \u2014 it makes buses run and games work. But YOUR private things (name, home, school, photos) belong to <strong>you</strong>, and you get to protect them.'],
        ex: { t: 'One ordinary day\u2019s shadow', i: ['b|Transit card: where you got on and off', 'b|Game app: when and how long you played', 'b|Shop camera: that you walked past at 4pm', 'g|Your diary at home: collects nothing!'] },
        co: ['The park test', 'Would you tell it to a stranger at the park? No? Then don\u2019t type it into an app either.', true],
        sort: { name: 'SHADOW CHECK', prompt: 'Sort: fine to share, or keep private?', g: 'OK TO SHARE \ud83d\udfe2', r: 'KEEP PRIVATE \ud83d\udd34', intro: 'GREEN = safe for apps and AI. RED = private \u2014 yours to protect.', items: ['My favourite colour|green', 'My full home address|red', 'A drawing idea|green', 'My school\u2019s name and my class|red', 'A question about volcanoes|green', 'A photo of my face|red', 'My password|red', 'My favourite football team|green'] },
        quiz: { q: 'What is your \u201cdata shadow\u201d?', o: ['A|A spooky shape that follows you at night', 'B|All the little bits of information machines collect about you|1', 'C|A photo filter'], rf: 'Every tap, click and camera adds a bit. Knowing your shadow exists is the first step to protecting it.', wf: 'It\u2019s not spooky and not a filter \u2014 it\u2019s the trail of <b>information</b> machines collect about your day.' },
        learned: 'Machines quietly collect <b>data</b> as you move through your day \u2014 and which things are yours to keep private.', take: 'Draw your data shadow for one day and show a grown-up. Then decide together: what should stay private?' },
      { n: 8, name: 'Community Showcase 1', act: '\u201cAI Spotters\u201d poster walk for families.', hook: 'Families annotate posters with their own examples', actShort: 'Build your AI Spotters poster',
        sign: 'circle', glyph: '\ud83c\udfc1', h: 'Show your town what you spotted', lt: 'SHOWCASE',
        p: ['Semester 1 done! You can spot AI, write robot-proof steps, see pixels, hear wiggles, sort by features, and protect your data shadow. Time to <strong>teach your family</strong> \u2014 with a poster walk.', 'Teaching is the final test: if you can explain it to your family so THEY start spotting AI too, you truly own it.'],
        ex: { t: 'A great Spotter poster has', i: ['g|One AI you found near home \u2014 drawn big', 'g|WHY it\u2019s AI (it learned! it decides!)', 'g|One thing it should never be told (private!)', 'g|A blank corner for family examples'] },
        co: ['Family mission', 'Leave a marker by your poster \u2014 visitors add their own AI sightings. Best annotated poster wins the Spotter cup!'],
        build: 'Plan your showcase poster. CLEAR: which AI you\u2019re showing and why it counts as AI. KIND: a fun question to ask visiting families. SAFE: check \u2014 nothing private on the poster (no addresses, no full names).',
        quiz: { q: 'A visitor asks: \u201cHow do I know if my rice cooker is AI?\u201d Best Spotter answer?', o: ['A|\u201cEverything electric is AI\u201d', 'B|\u201cDoes it learn or decide anything? If it just heats and switches off \u2014 machine, not AI\u201d|1', 'C|\u201cAsk the shop\u201d'], rf: 'That\u2019s the Spotter test: learning or deciding = AI. Plain switching = machine.', wf: 'Not everything electric is AI! The test is: does it <b>learn</b> or <b>decide</b>? A basic cooker just switches off.' },
        learned: 'Everything from Semester 1 \u2014 spotting AI, exact steps, pixels, sound, features and your data shadow \u2014 well enough to TEACH it.', take: 'Semester 2 is next: \u201cTeaching Machines\u201d. You stop spotting AI and start TRAINING it!' },
    ] },
    { name: 'Teaching Machines', mods: [
      { n: 9, name: 'Rules vs. Learning', act: 'Two teams guess fruit: one with written rules, one by seeing many examples. Which learns better?', hook: '\u27e8Local fruits, vegetables, or fish\u27e9', actShort: 'Rules team vs. examples team \u2014 who wins?',
        sign: 'rect', glyph: 'VS', h: 'Two ways to teach a machine', lt: 'RULES VS. LEARNING',
        p: ['Way 1: write <strong>rules</strong>. \u201cIf it\u2019s yellow and curved \u2192 banana.\u201d Works\u2026 until a green banana shows up.', 'Way 2: show <strong>lots of examples</strong> and let the machine find the patterns itself. That\u2019s <strong>machine learning</strong> \u2014 and for messy real things (fruit, faces, voices), examples usually beat rules.'],
        ex: { t: 'Why rules crack', i: ['b|\u201cYellow and curved\u201d \u2192 fails on green bananas', 'b|You\u2019d need a thousand rules for every odd fruit', 'g|1,000 example photos \u2192 the machine finds patterns you\u2019d never write down'] },
        co: ['Big word unlocked', 'Machine learning = teaching by examples instead of rules. You\u2019ll use it for real in Module 11!'],
        sort: { name: 'RULES OR LEARNING?', prompt: 'Which way would work better for each job?', g: 'WRITE RULES \ud83d\udfe2', r: 'LEARN FROM EXAMPLES \ud83d\udd34', intro: 'GREEN = simple and exact, rules win. RED = messy real-world stuff, examples win.', items: ['Add 10% to every price|green', 'Recognise any dog in any photo|red', 'Ring the bell at 9:00 sharp|green', 'Tell ripe from unripe mangoes by sight|red', 'Count words in a sentence|green', 'Understand handwriting|red'] },
        quiz: { q: 'The rules team keeps losing at fruit-guessing. Why?', o: ['A|Real fruit is too messy and varied for a short list of rules|1', 'B|They wrote the rules too neatly', 'C|Fruit changes every day'], rf: 'Messy real things break neat rules. Examples let the machine handle the mess.', wf: 'Neatness isn\u2019t the problem \u2014 real fruit is too <b>varied</b> for short rules. That\u2019s why examples win.' },
        learned: 'Two ways to teach machines \u2014 <b>rules</b> for exact jobs, <b>learning from examples</b> for messy real-world ones.', take: 'When AI amazes you, remember: nobody wrote a rule for that \u2014 it learned from examples. Which means the examples matter\u2026 a LOT.' },
      { n: 10, name: 'Train Your Human Classifier', act: 'Kids \u201ctrain\u201d a blindfolded classmate with example cards \u2014 then break it with a tricky example.', hook: 'Examples drawn from \u27e8local animals & plants\u27e9', actShort: 'Train a friend \u2014 then break your model!',
        sign: 'circle', glyph: 'TRAIN', h: 'Good examples make good learners', lt: 'TRAINING',
        p: ['Today your classmate IS the machine. Feed them example cards \u2014 \u201cspiky + green = cactus\u201d \u2014 and watch them learn. Then the fun part: <strong>break them</strong> with a tricky example they never saw.', 'That\u2019s exactly how real AI training works: the machine is only as good as its <strong>examples</strong>. Weird new case? Expect a funny mistake.'],
        ex: { t: 'Training rules of thumb', i: ['g|Many examples > few examples', 'g|Show the ODD ones too (green bananas!)', 'b|Only perfect examples \u2192 breaks on real life', 'g|Test with cases it never saw'] },
        co: ['Breaking is science', 'Finding what fools your model isn\u2019t naughty \u2014 it\u2019s exactly what real AI testers do all day.'],
        build: 'Design a training set! CLEAR: what should your \u201chuman classifier\u201d learn to tell apart (two local animals or plants)? KIND: what 5 example cards will you show them? SAFE: one tricky test card they have NOT seen \u2014 don\u2019t reveal it early.',
        quiz: { q: 'Your friend learned fruit from 5 perfect photos, then failed on a bumpy real mango. What went wrong?', o: ['A|Your friend wasn\u2019t listening', 'B|The training examples were too few and too perfect|1', 'C|Mangoes are impossible to learn'], rf: 'Small, too-perfect training sets break on real life. More variety in = fewer surprises out.', wf: 'It\u2019s the <b>training set</b>: too few, too perfect. Real life is bumpy \u2014 the examples must be too.' },
        learned: 'Training = showing examples, and a model is only as good as its examples \u2014 few or too-perfect ones make it break.', take: 'Next module you train a REAL model. Bring what you learned: variety in the examples!' },
      { n: 11, name: 'My First Real Model', act: 'Green Licence gate. Supervised class use of a child-safe image classifier to recognize local objects.', hook: 'Classify \u27e8local leaves, coins, gestures, or craft items\u27e9', actShort: 'Train a REAL image classifier (gate module!)',
        sign: 'circle', glyph: 'GO!', h: 'Today you train a real AI', lt: 'FIRST MODEL', lsub: 'green licence gate \u00b7 with your teacher',
        p: ['This is the <strong>Green Licence gate</strong> \u2014 your first REAL machine learning. With your teacher, you\u2019ll show a child-safe classifier examples of local objects (leaves, coins, gestures) and watch it learn to tell them apart.', 'Remember the recipe: <strong>varied examples in</strong>, test with new ones, and keep every mistake for the Mistake Museum.'],
        ex: { t: 'Gate checklist', i: ['g|Teacher\u2019s account, class screen \u2014 supervised', 'g|20+ varied examples per thing', 'g|Test with objects it never saw', 'b|NO photos of faces or private things in training'] },
        co: ['Licence rule', 'Green Licence = supervised, whole-class use only. Your teacher drives the account; you drive the learning.', true],
        quiz: { q: 'Your classifier confuses two leaf types. What\u2019s the BEST fix?', o: ['A|Shout at the computer', 'B|Add more varied examples of both leaves and retrain|1', 'C|Delete the model and give up'], rf: 'More varied examples \u2192 clearer patterns \u2192 better model. That\u2019s real ML engineering!', wf: 'Machines can\u2019t hear shouting \ud83d\ude04 The fix is always the same: more <b>varied examples</b>, then retrain.' },
        sort: { name: 'TRAINING SET CHECK', prompt: 'Sort: does it belong in the class training set?', g: 'GOOD TRAINING DATA \ud83d\udfe2', r: 'LEAVE IT OUT \ud83d\udd34', intro: 'GREEN = safe, varied, on-topic. RED = private or off-topic.', items: ['20 photos of local leaves, all angles|green', 'A photo with a classmate\u2019s face in it|red', 'Coins on light AND dark backgrounds|green', 'Someone\u2019s house number|red', 'Blurry leaf photo (real life is blurry!)|green', 'A random cat meme|red'] },
        learned: 'You trained a <b>real image classifier</b>: varied examples in, test on new objects, mistakes recorded \u2014 and you passed the Green Licence gate!', take: 'Your model\u2019s mistakes are treasure \u2014 bring them to Module 12 for the Mistake Museum.' },
      { n: 12, name: 'When Machines Get It Wrong', act: 'Feed the class model confusing examples; keep a \u201cMistake Museum\u201d.', hook: 'Include items the training set ignored \u2014 \u27e8local skin tones, garments, foods\u27e9', actShort: 'Collect the best mistakes for the museum',
        sign: 'triangle', glyph: '!', h: 'Every mistake tells a story', lt: 'MISTAKE MUSEUM',
        p: ['Your model called a mango a \u201cball\u201d? <strong>Fantastic.</strong> Every mistake points at a gap in the training examples \u2014 something the model never got to see.', 'The serious part: when training sets ignore some people\u2019s <strong>skin tones, clothes or foods</strong>, the model fails on THEM. Mistakes aren\u2019t just funny \u2014 they show who was left out.'],
        ex: { t: 'Museum-worthy mistakes', i: ['g|Mango \u2192 \u201cball\u201d (never saw round fruit)', 'g|Local dress \u2192 \u201ccurtain\u201d (nobody\u2019s clothes in the set)', 'g|Dark-skinned hand not detected (skin tones missing!)', 'b|\u201cIt just glitched\u201d \u2014 no! Find the gap'] },
        co: ['The museum rule', 'Every exhibit needs a label: WHAT went wrong, and WHICH missing examples caused it.', true],
        sort: { name: 'WHY DID IT FAIL?', prompt: 'Match each mistake to its cause \u2014 gap in examples, or genuinely hard?', g: 'GAP IN THE EXAMPLES \ud83d\udfe2', r: 'GENUINELY HARD CASE \ud83d\udd34', intro: 'GREEN = the training set left something out. RED = even humans would squint.', items: ['Fails on every dark-skinned hand|green', 'Fails on a leaf photographed in fog|red', 'Calls all local garments \u201ccurtains\u201d|green', 'Confuses two nearly identical coins|red', 'Never recognises the local flatbread|green', 'Misses an object 99% hidden behind a box|red'] },
        quiz: { q: 'The class model fails on every photo of Amina\u2019s grandmother\u2019s dress. The lesson?', o: ['A|The dress is wrong', 'B|The training set had no clothes like hers \u2014 someone was left out of the examples|1', 'C|AI hates dresses'], rf: 'Exactly. Fix the DATA: add examples of everyone\u2019s clothes, retrain, test again.', wf: 'Nothing\u2019s wrong with the dress! The <b>training set</b> left her clothes out \u2014 that\u2019s the gap to fix.' },
        learned: 'Mistakes reveal <b>gaps in training data</b> \u2014 and when data ignores some people, the model fails on them. That\u2019s why we keep a Mistake Museum.', take: 'New house rule: when AI gets it wrong, don\u2019t say \u201cstupid computer\u201d \u2014 ask \u201cwhat examples were missing?\u201d' },
      { n: 13, name: 'Fair Isn\u2019t Automatic', act: 'Cookie-sharing simulation: a \u201crule\u201d that seems fair but isn\u2019t; connect to a model trained only on some kids\u2019 drawings.', hook: 'Fairness framed via \u27e8local sharing customs \u2014 harvest, iftar, potluck, ubuntu\u27e9', actShort: 'Find the unfair rule hiding in a fair-sounding one',
        sign: 'octagon', glyph: 'FAIR?', h: 'A rule can sound fair and BE unfair', lt: 'FAIRNESS',
        p: ['\u201cOne cookie per person who lines up fastest\u201d \u2014 sounds fair! Unless some kids sit far away, or were never told the line formed. Rules that ignore <strong>who starts where</strong> can be unfair while sounding equal.', 'Same with AI: train a drawing-recogniser only on SOME kids\u2019 drawings and it works great for them \u2014 and badly for everyone else. Fair isn\u2019t automatic. It has to be <strong>checked</strong>.'],
        ex: { t: 'Fair-sounding, unfair-being', i: ['b|\u201cFastest to the front gets it\u201d \u2014 who sat closest?', 'b|\u201cThe model treats every drawing the same\u201d \u2014 trained on whose?', 'g|Check: does it work equally well for EVERYONE?', 'g|Your town\u2019s sharing customs already solve this \u2014 ask the elders'] },
        co: ['The fairness question', 'Never ask \u201cis the rule the same for everyone?\u201d Ask \u201cdoes it WORK for everyone?\u201d Different question, better answer.'],
        quiz: { q: 'A model trained only on Team A\u2019s drawings scores Team A higher \u201cevery time, by the same rule\u201d. Fair?', o: ['A|Yes \u2014 same rule for everyone means fair', 'B|No \u2014 the training data favoured Team A before the rule even ran|1', 'C|Fairness doesn\u2019t apply to machines'], rf: 'The unfairness was baked into the DATA. Same-rule-for-all can\u2019t fix a one-sided training set.', wf: 'Same rule \u2260 fair when the <b>training data</b> already favoured one team. Check the data, not just the rule.' },
        sort: { name: 'FAIR CHECK', prompt: 'Sort these class-model plans:', g: 'FAIR BY DESIGN \ud83d\udfe2', r: 'HIDDEN UNFAIRNESS \ud83d\udd34', intro: 'GREEN = everyone\u2019s included from the start. RED = someone\u2019s quietly left out.', items: ['Collect drawings from EVERY kid before training|green', 'Train on whoever submits first|red', 'Test the model on each team separately|green', 'Only test on the teacher\u2019s examples|red', 'Ask \u201cwho might this miss?\u201d before starting|green', '\u201cIt works for me, ship it\u201d|red'] },
        learned: 'Fairness must be <b>designed and checked</b> \u2014 equal rules on unequal data still produce unfair results.', take: 'Borrow your town\u2019s sharing wisdom: before any AI project, ask \u201cwho might this leave out?\u201d' },
      { n: 14, name: 'Machines That Talk', act: 'Teacher-mediated chatbot demo on the projector; the class hunts for one made-up \u201cfact\u201d about their own town.', hook: 'The hallucination is about \u27e8local history\u27e9 \u2014 elders verify', actShort: 'Catch the chatbot inventing a \u201cfact\u201d',
        sign: 'triangle', glyph: 'HMM', h: 'Confident is not the same as correct', lt: 'TALKING MACHINES',
        p: ['Chatbots build sentences by predicting <strong>what word probably comes next</strong>. That makes them sound smooth and sure \u2014 even when they\u2019re inventing things. Made-up \u201cfacts\u201d have a name: <strong>hallucinations</strong>.', 'Today the class catches one red-handed: ask about YOUR town\u2019s history and check the answers against people who actually know \u2014 the elders.'],
        ex: { t: 'Hallucination tells', i: ['b|Names a festival your town never had', 'b|Gets the founding date confidently wrong', 'b|Invents a \u201cfamous local hero\u201d nobody knows', 'g|Real check: elders, library, town records'] },
        co: ['Golden rule', 'A chatbot\u2019s answer is a CLAIM, not a fact. Smooth voice, sure tone \u2014 still check it.', true],
        sort: { name: 'TRUST OR CHECK?', prompt: 'The chatbot said it. Sort:', g: 'FINE TO USE AS-IS \ud83d\udfe2', r: 'CHECK BEFORE BELIEVING \ud83d\udd34', intro: 'GREEN = ideas and wording, low stakes. RED = facts that could be invented.', items: ['A rhyme for your poem|green', 'The year your town was founded|red', 'Three story ideas about a dragon|green', '\u201cYour local river is 212 km long\u201d|red', 'A nicer way to word your sentence|green', 'What the old market was called|red'] },
        quiz: { q: 'The chatbot says, very confidently, that your town held a \u201cGreat Kite War in 1892\u201d. Nobody\u2019s heard of it. What is this?', o: ['A|A secret history only AI knows', 'B|Probably a hallucination \u2014 the machine predicted plausible-sounding words|1', 'C|Proof the elders forgot'], rf: 'Confident + plausible + unverifiable = classic hallucination. Elders and archives beat autocomplete.', wf: 'AI has no secret archives \u2014 it <b>predicts words</b>. Unheard-of \u201cfacts\u201d are hallucinations until a real source confirms.' },
        learned: 'Chatbots predict <b>likely words</b>, not truth \u2014 so they hallucinate. Confident tone means nothing; checking does.', take: 'Family game: ask a chatbot about your town, then fact-check with an elder. Score a point per catch!' },
      { n: 15, name: 'Real or AI-Made?', act: 'Spot-the-fake gallery: real vs. AI images of familiar places; learn the tell-tale signs.', hook: 'Images of \u27e8the learners\u2019 own city / landscape\u27e9', actShort: 'Spot the AI-made photo of your own town',
        sign: 'octagon', glyph: 'FAKE?', h: 'Your eyes need new tricks', lt: 'SPOT THE FAKE',
        p: ['AI can now draw a photo of your own street that never happened. Scary? A little. Beatable? <strong>Yes</strong> \u2014 fakes leave clues, and knowing your own town is your superpower.', 'Look for: hands and fingers gone weird, melted text on signs, shadows pointing different ways, buildings that don\u2019t QUITE match reality \u2014 and that too-smooth, too-perfect glow.'],
        ex: { t: 'Tell-tale signs', i: ['g|Count fingers. Seriously.', 'g|Read the signs \u2014 AI text melts', 'g|Check shadows: same direction?', 'g|You know your town \u2014 does that corner even exist?'] },
        co: ['Home advantage', 'AI has seen a million towns \u2014 but not yours like YOU have. Locals catch local fakes fastest.'],
        sort: { name: 'REAL OR AI-MADE?', prompt: 'Sort the clues:', g: 'SMELLS REAL \ud83d\udfe2', r: 'SMELLS AI-MADE \ud83d\udd34', intro: 'GREEN = what real photos do. RED = classic AI giveaways.', items: ['Sign text is crisp and spells right|green', 'The baker has six fingers|red', 'Shadows all point the same way|green', 'The shop\u2019s name is melted squiggles|red', 'That street corner matches real life|green', 'Everything glows weirdly smooth and perfect|red'] },
        quiz: { q: 'Best FIRST check when a photo of your town looks suspicious?', o: ['A|Share it quickly and ask everyone', 'B|Zoom in: fingers, sign text, shadows \u2014 then compare with the real place|1', 'C|Believe it if it looks pretty'], rf: 'Inspect first, share never (until verified). Fakes crumble under a good zoom.', wf: 'Never share first! <b>Zoom in</b> \u2014 fingers, text, shadows \u2014 then check against the real place you know.' },
        learned: 'AI images have <b>tell-tale flaws</b> \u2014 fingers, text, shadows, wrong details \u2014 and local knowledge catches local fakes.', take: 'New reflex: cool photo \u2192 zoom in BEFORE you believe or share. Teach the fingers trick to your family.' },
      { n: 16, name: 'Community Showcase 2', act: 'Families play \u201cReal or AI?\u201d and visit the Mistake Museum.', hook: 'Guest judge: \u27e8a local elder or journalist\u27e9', actShort: 'Run the Real-or-AI game for families',
        sign: 'circle', glyph: '\ud83c\udfc1', h: 'Semester 2 \u2014 show what you trained', lt: 'SHOWCASE',
        p: ['What a semester: you trained a real model, curated its funniest mistakes, caught a chatbot inventing history, and learned to spot fake photos of your own town. Tonight, <strong>families play your games</strong>.', 'Two stations: the <strong>Mistake Museum</strong> (you explain WHY each mistake happened) and <strong>Real or AI?</strong> (families guess, you reveal the tells). A local elder or journalist judges.'],
        ex: { t: 'Showcase stations', i: ['g|Mistake Museum \u2014 every exhibit labelled with its data gap', 'g|Real or AI? \u2014 5 image pairs of YOUR town', 'g|Model demo \u2014 classify a leaf live on stage', 'g|Family corner \u2014 they try to break your model!'] },
        co: ['Judge\u2019s hint', 'Judges love WHY. \u201cIt failed because the training set had no X\u201d beats \u201cit\u2019s funny\u201d every time.'],
        build: 'Plan your station. CLEAR: which exhibit or game you\u2019re running and what visitors will do. KIND: how you\u2019ll explain a mistake WITHOUT making the model (or a guesser) look silly. SAFE: check every image and exhibit \u2014 no faces, no private info.',
        quiz: { q: 'A family member asks: \u201cIf models make mistakes, are they useless?\u201d Best answer?', o: ['A|\u201cYes, never trust machines\u201d', 'B|\u201cNo \u2014 mistakes show the data gaps. Fix the examples, retrain, and it improves. Just never trust it blindly\u201d|1', 'C|\u201cModels never make mistakes\u201d'], rf: 'That\u2019s a trained AI citizen talking: useful + improvable + never blindly trusted.', wf: 'Neither extreme! Models are useful AND flawed \u2014 mistakes reveal <b>data gaps</b> you can fix. Trust, but verify.' },
        learned: 'The whole \u201cTeaching Machines\u201d semester \u2014 training, mistakes, hallucinations and fakes \u2014 taught well enough to run a family game night.', take: 'Semester 3 next: \u201cAI in My Community\u2019s Work\u201d. You take everything outside \u2014 to the fields, shops and clinics of your town.' },
    ] },
    { name: 'AI in My Community\u2019s Work', mods: [
      { n: 17, name: 'AI Field Walk', act: 'Guided walk: where could sensors and AI exist here \u2014 traffic, irrigation, clinic, port, market?', hook: 'The walk \u27e8is\u27e9 the localization', actShort: 'Walk the town, map where AI could live',
        sign: 'rect', glyph: 'WALK', h: 'Your town is full of AI-shaped spaces', lt: 'FIELD WALK',
        p: ['Today class happens OUTSIDE. Walk the town with new eyes: where does something get <strong>counted, watched, predicted or sorted</strong>? Traffic, water pumps, the clinic queue, the market scales \u2014 each is a place AI could help\u2026 or already quietly does.', 'Fill your field notebook: WHAT happens there, WHAT could be sensed, and WHO it would help or bother.'],
        ex: { t: 'Field notebook prompts', i: ['g|Traffic corner: could sensors count and time the lights?', 'g|Irrigation: could soil sensors say when to water?', 'g|Clinic: could a queue predictor cut the waiting?', 'b|Also note: would a camera HERE bother people?'] },
        co: ['Field rule', 'Observe, don\u2019t photograph people. Your notebook takes notes \u2014 not faces.', true],
        sort: { name: 'SENSE-ABLE?', prompt: 'Sort what you saw on the walk:', g: 'A SENSOR COULD MEASURE IT \ud83d\udfe2', r: 'NEEDS A HUMAN \ud83d\udd34', intro: 'GREEN = countable, measurable. RED = needs judgement, trust or care.', items: ['How many cars pass per minute|green', 'Whether the soil is dry|green', 'Whether a patient feels scared|red', 'The queue length at the clinic|green', 'If a price is FAIR|red', 'Rainfall this week|green', 'Whether the market feels friendly today|red'] },
        quiz: { q: 'On the walk you spot a long clinic queue. What\u2019s the AI-shaped question to write down?', o: ['A|\u201cCould a machine replace the doctor?\u201d', 'B|\u201cCould sensors + patterns predict busy hours so people wait less?\u201d|1', 'C|\u201cShould we put cameras on everyone?\u201d'], rf: 'AI helps best at the measurable part \u2014 predicting the queue \u2014 while doctors stay human.', wf: 'Not replacing doctors, not cameras-on-everyone! The AI-shaped part is the <b>measurable</b> bit: predicting busy hours.' },
        learned: 'How to see <b>AI-shaped spaces</b>: places where things get counted, watched or predicted \u2014 and where humans must stay in charge.', take: 'Keep the field notebook going \u2014 Module 22 turns your best observation into a design.' },
      { n: 18, name: 'Helping Hands: AI & Jobs', act: 'Interview a family member: could a machine help or harm their work?', hook: '\u27e8Local occupations \u2014 fishing, farming, tailoring, nursing, driving\u27e9', actShort: 'Interview a worker: help or harm?',
        sign: 'rect', glyph: 'WORK', h: 'Tools change work \u2014 people decide how', lt: 'AI & JOBS',
        p: ['Ask a fisher, farmer, tailor, nurse or driver about their day and you\u2019ll find two kinds of tasks: the <strong>repeated, countable</strong> parts (logging catch, tracking stock) and the <strong>human</strong> parts (judging the weather\u2019s mood, comforting a patient, haggling kindly).', 'AI tends to help with the first kind \u2014 and can\u2019t touch the second. The interview\u2019s job: find BOTH in someone you love, and hear what THEY want.'],
        ex: { t: 'Interview questions that work', i: ['g|\u201cWhat part of your day repeats over and over?\u201d', 'g|\u201cWhat part could no machine ever do?\u201d', 'g|\u201cWhat would you WANT a helper to take off your plate?\u201d', 'b|Skip: \u201cAre you scared of robots?\u201d (leading!)'] },
        co: ['Respect first', 'Workers are the experts of their own work. We ask and listen \u2014 we don\u2019t tell them what AI \u201cshould\u201d do.'],
        build: 'Prepare your interview. CLEAR: who you\u2019ll interview and their job. KIND: three open questions from today (no leading ones!). SAFE: how you\u2019ll keep their answers private \u2014 first name only, and ask before sharing anything.',
        quiz: { q: 'Your uncle the tailor says measuring and re-measuring eats his day, but choosing fabrics with customers is the joy. Where could AI fit?', o: ['A|Choosing the fabrics \u2014 it has better taste', 'B|The measuring \u2014 repeated and countable \u2014 leaving the joyful part human|1', 'C|Nowhere \u2014 tailoring must never change'], rf: 'Help with the repeated part, protect the human part. That\u2019s the pattern for every job.', wf: 'AI has no taste \u2014 and jobs CAN change well. The fit is the <b>repeated, countable</b> part: measuring.' },
        learned: 'AI reshapes jobs by taking <b>repeated, countable tasks</b> \u2014 and the human parts (judgement, care, trust) stay human.', take: 'Share your interview findings at dinner. Bonus: ask a SECOND worker and compare.' },
      { n: 19, name: 'Weather & Water', act: 'Simple data logging with a rain gauge and temperature chart; predict tomorrow from patterns.', hook: '\u27e8Monsoon, harmattan, snow, drought\u27e9 \u2014 whatever is local', actShort: 'Log real weather, predict tomorrow',
        sign: 'circle', glyph: '\ud83c\udf27', h: 'Prediction = patterns + humility', lt: 'WEATHER DATA',
        p: ['A rain gauge, a thermometer, a chart on the wall \u2014 congratulations, you\u2019re running a <strong>data pipeline</strong>. Log every day, and patterns appear: after THOSE clouds, rain; three hot days, then wind.', 'Predicting from patterns is exactly what weather AI does \u2014 with millions of gauges. And like you, it\u2019s sometimes wrong: patterns bend. Good forecasters say \u201cprobably\u201d, not \u201ccertainly\u201d.'],
        ex: { t: 'Your weather station', i: ['g|Same time, same place, every day \u2014 or the data lies', 'g|Chart it: patterns hide in rows, jump out of pictures', 'g|Predict tomorrow, then CHECK yourself tomorrow', 'b|One weird day doesn\u2019t break the pattern \u2014 or prove it'] },
        co: ['Why it matters here', 'Your region\u2019s season \u2014 monsoon, harmattan, drought \u2014 is the pattern your farmers already read. You\u2019re learning their skill, with numbers.'],
        quiz: { q: 'Your chart shows rain followed THOSE big grey clouds 8 times out of 10. Tonight: big grey clouds. Best prediction?', o: ['A|\u201cIt WILL rain, guaranteed\u201d', 'B|\u201cRain is likely \u2014 about 8 in 10 \u2014 but not certain\u201d|1', 'C|\u201cImpossible to say anything\u201d'], rf: 'Patterns give probabilities, not promises. That\u2019s honest forecasting \u2014 human or AI.', wf: 'Not guaranteed, not impossible \u2014 patterns give <b>probabilities</b>. \u201cLikely, 8 in 10\u201d is the honest call.' },
        sort: { name: 'GOOD DATA HABITS', prompt: 'Sort the weather-station habits:', g: 'GOOD DATA HABIT \ud83d\udfe2', r: 'DATA SPOILER \ud83d\udd34', intro: 'GREEN = keeps the pattern trustworthy. RED = quietly ruins it.', items: ['Reading the gauge at 8am sharp daily|green', 'Skipping rainy days (too wet outside)|red', 'Writing 0 when there was no rain|green', 'Guessing yesterday\u2019s missed reading|red', 'Moving the gauge somewhere new each week|red', 'Noting \u201cgauge knocked over \u2014 data missing\u201d|green'] },
        learned: 'How prediction works: <b>steady data \u2192 patterns \u2192 probabilities</b> \u2014 and why honest forecasts say \u201clikely\u201d, not \u201ccertainly\u201d.', take: 'Keep the station running a full month. Your chart becomes real evidence about your town\u2019s season.' },
      { n: 20, name: 'Maps & Machines', act: 'Route-finding on a hand-drawn town map; act out \u201cshortest path\u201d.', hook: 'The children\u2019s own \u27e8school-to-home routes\u27e9', actShort: 'Find shortest paths on your own town map',
        sign: 'rect', glyph: 'MAP', h: 'How machines find the way', lt: 'SHORTEST PATH',
        p: ['How does a map app pick your route? It turns the town into dots (corners) and lines (streets), each line with a <strong>cost</strong> \u2014 minutes, metres, mud. Then it tries paths cleverly, always extending the cheapest one so far.', 'Act it out on your hand-drawn map: walk the school-to-home routes, add up the costs, and feel the algorithm think.'],
        ex: { t: 'Costs a route can count', i: ['g|Distance in steps', 'g|Time \u2014 the muddy shortcut is SLOW in rain', 'g|Safety \u2014 a busy road costs extra', 'b|A map that\u2019s wrong \u2192 confident nonsense routes'] },
        co: ['Garbage in, garbage out', 'The finest algorithm on a wrong map gives wrong answers politely. Data quality first \u2014 always.'],
        quiz: { q: 'The app sends everyone down the footbridge path \u2014 which flooded last month. Why?', o: ['A|The app wants people wet', 'B|Its map data doesn\u2019t know about the flood \u2014 old data in, wrong route out|1', 'C|Shortest paths don\u2019t exist any more'], rf: 'Routes are only as good as the map data. Locals knew; the data didn\u2019t. Update the data!', wf: 'The app isn\u2019t mean \u2014 its <b>map data</b> is stale. Old data in, confidently wrong route out.' },
        sort: { name: 'COST OR NOT?', prompt: 'Planning a school route \u2014 sort what the algorithm can use:', g: 'COUNTABLE COST \ud83d\udfe2', r: 'NOT A NUMBER \ud83d\udd34', intro: 'GREEN = measurable per street. RED = real, but not countable per line on a map.', items: ['Metres of walking|green', 'Minutes at each crossing|green', 'How adventurous the path feels|red', 'Number of busy roads crossed|green', 'Whether Grandma waves from her window|red', 'Steps of stairs to climb|green'] },
        learned: 'Route-finding = town as <b>dots, lines and costs</b>, plus a clever try-the-cheapest search \u2014 and stale map data means wrong routes.', take: 'Next time an app routes your family oddly, play detective: what cost or data did it get wrong?' },
      { n: 21, name: 'AI & My Language', act: 'Test translation of a local proverb; explore why machines struggle with our language.', hook: '\u27e8Proverbs, songs, or oral stories\u27e9 from the community', actShort: 'Translation-test a local proverb',
        sign: 'triangle', glyph: 'ABC', h: 'Some languages get less machine love', lt: 'LANGUAGE GAP',
        p: ['Feed a local proverb to a translator and watch it stumble. Why? Machines learn language from <strong>text on the internet</strong> \u2014 and some languages have millions of pages there, others barely any.', 'Less data = worse AI. It\u2019s not that your language is \u201chard\u201d \u2014 it\u2019s <strong>under-served</strong>. And proverbs are hardest of all: their meaning lives between the words.'],
        ex: { t: 'Why proverbs break translators', i: ['b|Word-for-word kills the meaning', 'b|Culture lives between the words', 'b|Little training text in the language', 'g|A bilingual elder beats the machine every time'] },
        co: ['Your superpower', 'Speaking an under-served language makes you the QUALITY CHECKER machines need. That\u2019s a job, by the way.'],
        quiz: { q: 'The translator turns your proverb into nonsense. The deepest reason?', o: ['A|Your language is too weird', 'B|The machine saw too little text in your language \u2014 and proverbs carry meaning beyond words|1', 'C|Proverbs are secrets machines aren\u2019t allowed to know'], rf: 'Under-served language + between-the-words meaning = machine stumble. Elders still hold the gold.', wf: 'No language is \u201ctoo weird\u201d! It\u2019s <b>data scarcity</b> plus meaning that lives between the words.' },
        sort: { name: 'MACHINE-EASY OR ELDER-NEEDED?', prompt: 'Sort the translation jobs:', g: 'MACHINE HANDLES IT \ud83d\udfe2', r: 'NEEDS A HUMAN \ud83d\udd34', intro: 'GREEN = plain, common phrases. RED = culture, poetry, between-the-words.', items: ['\u201cWhere is the bus station?\u201d|green', 'Grandmother\u2019s harvest proverb|red', '\u201cTwo teas, please\u201d|green', 'The joke that rhymes in our language|red', 'A shop\u2019s opening hours|green', 'The lullaby\u2019s hidden meaning|red'] },
        learned: 'Language AI quality follows <b>training data</b> \u2014 under-served languages get worse tools \u2014 and culture-rich text needs humans.', take: 'Record (with permission!) one elder\u2019s proverb and its real meaning. You\u2019re building the data your language deserves.' },
      { n: 22, name: 'Design a Helper', act: 'Teams sketch an AI helper for a real local problem \u2014 cardboard and role-play prototype.', hook: 'Problem nominated by \u27e8community survey\u27e9', actShort: 'Sketch an AI helper for a real problem',
        sign: 'circle', glyph: '\ud83d\udca1', h: 'Design starts with the problem, not the robot', lt: 'DESIGN A HELPER',
        p: ['Real designers don\u2019t start with \u201clet\u2019s use AI!\u201d \u2014 they start with a <strong>problem worth solving</strong>. Yours comes from the community survey: what does your town actually struggle with?', 'Then the design questions: WHO is it for? What does it <strong>sense</strong> (rain? queues? sounds)? What does it <strong>decide</strong>? What does it <strong>do</strong>? And the ubuntu question \u2014 who might it accidentally leave out? Cardboard + role-play = your prototype.'],
        ex: { t: 'The helper design sheet', i: ['g|PROBLEM: one sentence, from the survey', 'g|SENSES: what it measures', 'g|DECIDES: the pattern it looks for', 'g|DOES: the helpful action', 'b|Skipped question = design hole: who could it miss?'] },
        co: ['Honest option', 'The bravest design answer is sometimes \u201cthis problem doesn\u2019t need AI \u2014 it needs a bench and a shade tree.\u201d Real designers say so.'],
        build: 'Design your helper! CLEAR: the problem and who it\u2019s for (from the survey). KIND: what it senses, decides and does \u2014 and how it stays friendly to those it serves. SAFE: what it must NEVER collect (faces? names?) and who checks it\u2019s fair.',
        quiz: { q: 'Your team\u2019s idea: \u201cAn AI that watches everyone at the well and reports queue-jumpers.\u201d What\u2019s the design flaw?', o: ['A|Wells don\u2019t have electricity', 'B|Surveillance of neighbours breaks trust \u2014 the problem (fair queues) has kinder designs|1', 'C|Nothing \u2014 ship it'], rf: 'A queue-number ticket or a chalkboard might fix it without watching anyone. Kindest working design wins.', wf: 'Electricity is fixable \u2014 the flaw is <b>watching your neighbours</b>. Fair queues have kinder designs (tickets, chalkboards).' },
        learned: 'The design recipe: <b>problem \u2192 senses \u2192 decides \u2192 does</b>, plus the kindness check \u2014 and that \u201cno AI needed\u201d is a valid answer.', take: 'Keep the cardboard prototype safe \u2014 Module 23 stress-tests its kindness, and the capstone may build it for real.' },
      { n: 23, name: 'The Kindness Test', act: 'Ethics circle: does our helper respect privacy, fairness, elders, and the environment?', hook: '\u27e8Local values framework\u27e9 co-written with families', actShort: 'Stress-test your design\u2019s kindness',
        sign: 'octagon', glyph: '\u2764', h: 'Would your helper make Grandma proud?', lt: 'KINDNESS TEST',
        p: ['Time to hold your Module-22 design up to the light. The <strong>Kindness Test</strong> asks four questions, drawn from your families\u2019 own values: Does it respect <strong>privacy</strong>? Is it <strong>fair</strong> to everyone? Does it honour <strong>elders</strong> and tradition? Is it gentle on the <strong>environment</strong>?', 'Sit in a circle. No defending allowed at first \u2014 just listening. A design that survives the circle is a design worth building.'],
        ex: { t: 'The four questions', i: ['g|PRIVACY: what does it collect \u2014 and could it hurt someone?', 'g|FAIRNESS: who might it work badly for?', 'g|ELDERS: does it respect how things are done here?', 'g|EARTH: batteries, waste, water \u2014 what does it cost?'] },
        co: ['Circle rule', 'When someone finds a problem in your design, say \u201cthank you\u201d \u2014 they just saved your future users.', true],
        sort: { name: 'KIND OR UNKIND DESIGN?', prompt: 'Sort these helper features:', g: 'PASSES THE TEST \ud83d\udfe2', r: 'FAILS THE TEST \ud83d\udd34', intro: 'GREEN = respectful, fair, gentle. RED = would worry the circle.', items: ['Counts people in the queue WITHOUT camera or names|green', 'Records everyone\u2019s face \u201cjust in case\u201d|red', 'Works in the local language AND the school one|green', 'Only responds to smartphone owners|red', 'Solar-charged, repairable locally|green', 'New batteries shipped monthly, old ones binned|red'] },
        quiz: { q: 'The circle finds your helper works badly for elders who don\u2019t use phones. Best response?', o: ['A|\u201cElders can learn phones\u201d', 'B|\u201cThank you \u2014 let\u2019s add a no-phone way to use it\u201d and redesign|1', 'C|Remove elders from the plan'], rf: 'That\u2019s the test working: catch the gap, widen the design, include everyone.', wf: 'The design serves people \u2014 not the other way round. Say <b>thank you</b> and add a no-phone path.' },
        learned: 'The four-question <b>Kindness Test</b> \u2014 privacy, fairness, elders, environment \u2014 and how a listening circle makes designs stronger.', take: 'The Kindness Test works on REAL products too. Try it on any app your family uses tonight.' },
      { n: 24, name: 'Community Showcase 3', act: 'Paper-prototype fair; the community votes with tokens.', hook: '\u27e8Local leaders\u27e9 as \u201cinvestors\u201d with token budgets', actShort: 'Pitch your prototype to token investors',
        sign: 'circle', glyph: '\ud83c\udfc1', h: 'Pitch it like you built it (you did)', lt: 'SHOWCASE',
        p: ['Semester 3 ends the grown-up way: a <strong>prototype fair</strong>. Your cardboard helper, your field-walk evidence, your Kindness Test results \u2014 on one table. Local leaders walk the room with <strong>token budgets</strong> and invest in what convinces them.', 'A winning pitch has three beats: the <strong>problem</strong> (real, local, from the survey), the <strong>design</strong> (senses \u2192 decides \u2192 does), and the <strong>kindness proof</strong> (what the circle found, and how you fixed it).'],
        ex: { t: 'What investors reward', i: ['g|A problem they recognise from their own street', 'g|Honesty: \u201chere\u2019s what our design CAN\u2019T do\u201d', 'g|The fix you made after the Kindness Test', 'b|Buzzwords. Leaders smell them instantly.'] },
        co: ['Pitch secret', 'Say the problem in the first ten seconds. Investors fund problems they feel \u2014 not features they don\u2019t.'],
        build: 'Write your pitch! CLEAR: the problem in one sentence + your helper in two. KIND: the Kindness Test finding you fixed \u2014 be proud of it, not embarrassed. SAFE: what your helper refuses to collect, and who keeps checking it stays fair.',
        quiz: { q: 'An investor asks: \u201cWhat happens if your helper makes a mistake?\u201d Best answer?', o: ['A|\u201cIt won\u2019t \u2014 it\u2019s AI\u201d', 'B|\u201cIt will sometimes \u2014 here\u2019s who checks it, and here\u2019s the no-tech backup\u201d|1', 'C|\u201cMistakes are the user\u2019s fault\u201d'], rf: 'Investors trust teams who plan for failure. \u201cIt won\u2019t fail\u201d is the biggest red flag in tech.', wf: '\u201cIt won\u2019t fail\u201d is the classic red flag! Winners plan: <b>who checks it</b> + a no-tech backup.' },
        learned: 'How to pitch: <b>problem \u2192 design \u2192 kindness proof</b> \u2014 with honesty about limits as your strongest card.', take: 'Semester 4 is the Capstone: one team, one project, built for real. Rest up, Cadet.' },
    ] },
    { name: 'Junior Cadet Capstone', mods: [
      { n: '25\u201326', name: 'Pick & Plan', act: 'Teams pick one Semester-3 prototype to take further and plan the build.', hook: 'Client problem from the \u27e8community survey\u27e9', actShort: 'Choose your capstone and plan the build',
        sign: 'rect', glyph: 'PLAN', h: 'Choose one thing. Finish it.', lt: 'PICK & PLAN',
        p: ['Capstone begins! Your team picks ONE Semester-3 prototype \u2014 probably the one investors funded \u2014 and commits. The hard part isn\u2019t choosing what to build; it\u2019s choosing what <strong>NOT</strong> to build. Small and finished beats big and abandoned.', 'Then plan like builders: what\u2019s the <strong>smallest version that helps someone</strong>? Who does what? What do you need \u2014 and what will you do when (not if) something breaks?'],
        ex: { t: 'A real plan answers', i: ['g|The smallest version that still helps (your \u201cweek-one demo\u201d)', 'g|Roles: who builds, who tests, who talks to the client', 'g|Materials list \u2014 and the free/cardboard backup for each', 'b|\u201cWe\u2019ll figure it out later\u201d \u2014 later is where projects die'] },
        co: ['Cut it in half', 'Whatever you planned \u2014 cut it in half. Then it might actually fit the semester. (Every builder learns this the hard way.)'],
        build: 'Write the team plan. CLEAR: which prototype, and the smallest version that helps someone by week one. KIND: each teammate\u2019s role, matched to what they love doing. SAFE: your backup plan for the riskiest part \u2014 what breaks first, and what then?',
        quiz: { q: 'Your team wants ALL five features from the prototype fair. The capstone is 8 weeks. What do builders do?', o: ['A|Promise all five and hope', 'B|Pick the ONE feature that helps most, finish it, then add more if time remains|1', 'C|Quit \u2014 too hard'], rf: 'One finished helpful thing beats five half-built ones. Ship small, then grow.', wf: 'Hoping isn\u2019t a plan! Pick the <b>one feature that helps most</b>, finish it well \u2014 then grow if time allows.' },
        learned: 'Capstone planning: pick ONE thing, define the <b>smallest helpful version</b>, assign roles, and plan for what breaks.', take: 'Pin the plan on the wall. Next stop: the build itself \u2014 bring tape.' },
      { n: '27\u201328', name: 'Micro-Demo Build', act: 'A working micro-demo: block coding with pre-trained blocks where devices allow \u2014 or a full \u201cWizard-of-Oz\u201d role-played system where they don\u2019t.', hook: 'Delivery mode set by the \u27e8Infrastructure Reality Check\u27e9', actShort: 'Build the working micro-demo',
        sign: 'circle', glyph: 'BUILD', h: 'Make the smallest thing that works', lt: 'MICRO-DEMO',
        p: ['Build weeks! If your school has devices, wire your model with <strong>block coding</strong> and pre-trained blocks. If it doesn\u2019t \u2014 no shame, better theatre: a <strong>Wizard-of-Oz</strong> demo, where a hidden teammate plays the AI, following your written rules EXACTLY.', 'Both are real prototyping. The point is the same: someone uses your helper, and it <strong>actually helps</strong>. Test daily; write down every surprise.'],
        ex: { t: 'Build-week wisdom', i: ['g|Demo something every single day, however tiny', 'g|Wizard-of-Oz rule: the \u201cAI\u201d follows the script, never improvises', 'g|A surprise log: every weird thing testers do', 'b|Building in secret till the \u201cbig reveal\u201d \u2014 reveals mostly fail'] },
        co: ['The wizard\u2019s oath', 'If you\u2019re the hidden human playing the AI: follow your team\u2019s written rules exactly \u2014 even when they\u2019re silly. THAT\u2019s the real test of the design.'],
        quiz: { q: 'No tablets this month \u2014 the class runs a Wizard-of-Oz demo instead. Is it a \u201creal\u201d prototype?', o: ['A|No \u2014 without a computer it doesn\u2019t count', 'B|Yes \u2014 it tests the design, rules and user experience for real; pros do exactly this|1', 'C|Only if nobody finds out'], rf: 'Professional designers Wizard-of-Oz all the time. The design gets tested \u2014 that\u2019s what counts.', wf: 'It absolutely counts \u2014 pros do it! The <b>design and rules</b> get tested for real; the computer can come later.' },
        sort: { name: 'DEMO-WEEK CHOICES', prompt: 'Sort the build-week moves:', g: 'BUILDER MOVE \ud83d\udfe2', r: 'PROJECT KILLER \ud83d\udd34', intro: 'GREEN = keeps the demo alive. RED = how projects quietly die.', items: ['Test with a real user on day one|green', 'Wait until it\u2019s perfect to show anyone|red', 'Write down every surprise a tester causes|green', 'Add three new features mid-week|red', 'Practise the wizard\u2019s script until it\u2019s boring|green', 'Skip testing \u2014 \u201cwe know it works\u201d|red'] },
        learned: 'Prototyping for real: <b>build small, demo daily</b> \u2014 with blocks or with a rule-following human wizard. Both count.', take: 'Guard the surprise log \u2014 Modules 29\u201330 turn it into fairness and privacy evidence.' },
      { n: 29, name: 'Fairness Check', act: 'Test the demo the Kindness-Test way: who does it help, who does it miss?', hook: 'Judged against the \u27e8local values charter\u27e9', actShort: 'Audit your own demo for fairness',
        sign: 'octagon', glyph: 'FAIR?', h: 'Audit your own build \u2014 before others do', lt: 'FAIRNESS CHECK',
        p: ['Your demo works! Now the professional question: <strong>who does it work FOR?</strong> Test it with the youngest kid, the eldest elder, the left-hander, the non-phone-owner, the quietest voice in class.', 'Score it against the values charter your families wrote. Every gap you find now is a person you won\u2019t fail later. Auditing your own work isn\u2019t doubting it \u2014 it\u2019s finishing it.'],
        ex: { t: 'The fairness test squad', i: ['g|Someone the design DIDN\u2019T have in mind', 'g|An elder who\u2019ll say what they really think', 'g|A kid younger than any tester so far', 'b|Only your teammates \u2014 they know it too well to be fooled by it'] },
        co: ['Auditor\u2019s honour', 'Finding a fairness gap in your OWN project and reporting it out loud is the most grown-up move in this whole curriculum.', true],
        quiz: { q: 'Your queue helper works great in tests \u2014 but every tester was a classmate with a phone. What\u2019s missing?', o: ['A|Nothing \u2014 tests passed', 'B|The people least like you: elders, non-phone-owners, little kids \u2014 test with THEM|1', 'C|More classmates'], rf: 'A test squad that mirrors the whole town finds the gaps classmates never will.', wf: 'Passing tests with people <b>just like you</b> proves little. The gaps hide with elders, little kids, non-phone-owners.' },
        sort: { name: 'REAL AUDIT OR RUBBER STAMP?', prompt: 'Sort the fairness-check habits:', g: 'REAL AUDIT \ud83d\udfe2', r: 'RUBBER STAMP \ud83d\udd34', intro: 'GREEN = actually finds gaps. RED = just looks like checking.', items: ['Testing with an elder who dislikes gadgets|green', 'Testing only when the demo is \u201cready\u201d|red', 'Writing down the failure you\u2019re embarrassed by|green', 'Skipping the tester who \u201cuses it wrong\u201d|red', 'Scoring against the family values charter|green', 'Averaging away one person\u2019s bad result|red'] },
        learned: 'Self-auditing: test with the people <b>least like you</b>, score against the charter, and report gaps proudly.', take: 'One more audit next module \u2014 privacy. Bring the same honesty.' },
      { n: 30, name: 'Privacy Check', act: 'Trace every piece of info the helper uses. Anything private? Take it out.', hook: 'Rules from the \u27e8Risk & Law Snapshot\u27e9', actShort: 'Trace every byte your helper touches',
        sign: 'octagon', glyph: 'PRIV', h: 'If you don\u2019t need it, don\u2019t collect it', lt: 'PRIVACY CHECK',
        p: ['Follow the data like a detective: what does your helper <strong>see, hear, count or remember</strong>? List every single piece. Then the golden rule of privacy engineering: <strong>data minimization</strong> \u2014 if the helper works without it, take it out.', 'Names? Probably don\u2019t need them. Faces? Almost never. \u201cJust in case\u201d? That\u2019s how trouble starts. Your Risk & Law Snapshot says what\u2019s allowed \u2014 your conscience says what\u2019s right.'],
        ex: { t: 'The data-trace questions', i: ['g|What EXACTLY does it collect? (List every item)', 'g|Does the helper still work without each item?', 'g|Where does data live \u2014 and when is it deleted?', 'b|\u201cWe keep everything just in case\u201d \u2014 the classic mistake'] },
        co: ['Minimization magic', 'Counting people needs a number, not names. Measuring queues needs times, not faces. The helpful version is almost always the private version.', true],
        quiz: { q: 'Your helper logs each user\u2019s full name \u201cto make the report nicer\u201d. Privacy check says?', o: ['A|Keep it \u2014 nicer reports matter', 'B|Cut it \u2014 the helper works without names, so collecting them is pure risk|1', 'C|Collect MORE, just in case'], rf: 'Data minimization in action: works-without-it means take-it-out. The report survives.', wf: '\u201cNicer\u201d isn\u2019t \u201cneeded\u201d. If it <b>works without names</b>, names are pure risk \u2014 out they go.' },
        sort: { name: 'COLLECT OR CUT?', prompt: 'Your queue helper\u2019s data list \u2014 sort it:', g: 'KEEP \u2014 NEEDED \ud83d\udfe2', r: 'CUT \u2014 NOT NEEDED \ud83d\udd34', intro: 'GREEN = the helper truly needs it. RED = minimize it away.', items: ['Count of people waiting|green', 'Each person\u2019s full name|red', 'Time each queue started|green', 'Photos of people in line|red', 'Average wait per hour|green', 'Who queue-jumped, by name|red'] },
        learned: '<b>Data minimization</b>: trace every piece of data, keep only what the helper needs, delete the rest \u2014 by law AND by kindness.', take: 'You\u2019ve audited fairness AND privacy. Next: show the families what you built.' },
      { n: 31, name: 'Family Presentation', act: 'Present the project to families \u2014 explaining a concept to a grown-up is the test.', hook: 'Presented in \u27e8the home language\u27e9', actShort: 'Teach your project to the grown-ups',
        sign: 'circle', glyph: '\ud83c\udf99', h: 'If Grandma gets it, you\u2019ve got it', lt: 'FAMILY NIGHT',
        p: ['The real exam isn\u2019t a quiz \u2014 it\u2019s <strong>your family understanding your project</strong>. In the home language, no jargon allowed: what problem, what your helper senses-decides-does, what the audits found, what you fixed.', 'When Grandma nods and asks a sharp question back \u2014 THAT\u2019s a pass. Teaching is the strongest proof of learning there is.'],
        ex: { t: 'Jargon \u2192 family words', i: ['g|\u201cTraining data\u201d \u2192 \u201cthe examples we showed it\u201d', 'g|\u201cClassifier\u201d \u2192 \u201cit sorts things into piles\u201d', 'g|\u201cData minimization\u201d \u2192 \u201cwe only keep what we truly need\u201d', 'b|Using English tech words nobody at home uses'] },
        co: ['The question round', 'Family questions are the best test data your project will ever get. Write every single one down.'],
        build: 'Script your presentation. CLEAR: the problem and your helper, in home-language words a grandparent enjoys. KIND: the moment you\u2019ll thank your testers and the circle that found your gaps. SAFE: the privacy promise you\u2019ll make out loud \u2014 what your helper never collects.',
        quiz: { q: 'Mid-presentation, Grandma asks: \u201cBut what if it\u2019s wrong about the queue?\u201d Best answer?', o: ['A|\u201cIt\u2019s AI, it\u2019s never wrong\u201d', 'B|\u201cGood question! It IS sometimes \u2014 here\u2019s who checks it and what we do then\u201d|1', 'C|\u201cThat\u2019s too technical for tonight\u201d'], rf: 'Grandma asked THE professional question \u2014 and got the professional answer. Full marks.', wf: 'Grandma\u2019s question is the pro question! Honest answer: <b>it\u2019s sometimes wrong</b> + who checks + what happens then.' },
        learned: 'Explaining tech in <b>plain home-language words</b> is the true test of understanding \u2014 and family questions are gold.', take: 'One module left, Cadet. Graduation. Bring the whole family.' },
      { n: 32, name: 'Cadet Graduation', act: 'Recite the Cadet Code, present your favorite Mistake Museum entry, receive the Road Crew invitation.', hook: 'Celebration styled by the \u27e8Story & Symbol Bank\u27e9', actShort: 'Recite the Code, collect your licence!',
        sign: 'circle', glyph: '\ud83c\udf93', h: 'From spotter to builder \u2014 look how far', lt: 'GRADUATION',
        p: ['Module 1: you sorted \u201cmachine or human\u201d cards. Module 32: you\u2019ve trained models, audited fairness and privacy, and taught your whole family. Today you <strong>recite the Cadet Code</strong>, present your favourite Mistake Museum exhibit, and graduate.', 'And one more thing arrives with the certificate: an <strong>invitation to Road Crew</strong> \u2014 where you go under the hood, hunt real bias, and build for a real client. Ages 12\u201316. Your seat is saved.'],
        ex: { t: 'Ceremony order', i: ['g|The Cadet Code, recited together', 'g|Your favourite mistake \u2014 and WHY it happened (data gaps!)', 'g|Licence + family photo (with permission \u2014 you know the rules!)', 'g|The Road Crew invitation \ud83d\udee3\ufe0f'] },
        co: ['Why the mistake?', 'We graduate holding a MISTAKE, not a trophy \u2014 because knowing why machines fail is exactly what makes you safe around them.'],
        quiz: { q: 'Why does graduation feature your favourite MISTAKE instead of your best success?', o: ['A|Mistakes are funnier', 'B|Understanding why machines fail \u2014 the data gaps \u2014 is the deepest thing a Cadet learns|1', 'C|There were no successes'], rf: 'Anyone can demo a success. Explaining a failure\u2019s cause \u2014 that\u2019s mastery. Congratulations, graduate. \ud83c\udf93', wf: 'They ARE funny \u2014 but the point is deeper: explaining <b>why machines fail</b> is the Cadet superpower.' },
        sort: { name: 'CADET CODE · FINAL CHECK', prompt: 'One last sort, graduate \u2014 is it the Cadet way?', g: 'THE CADET WAY \ud83d\udfe2', r: 'NOT OUR WAY \ud83d\udd34', intro: 'GREEN = the Code you\u2019re about to recite. RED = everything you learned to avoid.', items: ['Double-check what AI tells you|green', 'Type your address into a chatbot|red', 'Tell a grown-up when something feels wrong|green', 'Trust it because it sounds confident|red', 'Keep secrets secret|green', 'Let AI do your thinking for you|red', 'Ask \u201cwho might this leave out?\u201d|green'] },
        learned: 'Everything, Cadet. Spotting AI, training it, breaking it, auditing it, and teaching it to your family \u2014 the full route map, driven.', take: 'Road Crew awaits (ages 12\u201316): under the hood, real audits, a real client. Switch tiers in your portal when you\u2019re ready. \ud83d\udee3\ufe0f' },
    ] },
  ],
});
